use crate::api::client::ApiClient;
use crate::models::{ResultWithDefaultError, TimeEntry};
use crate::utilities;
use chrono::{Datelike, NaiveDate, Utc};
use std::collections::BTreeMap;
use std::io::{self, Write};

pub struct BillWeeklyCommand;

/// Bill only explicitly billable, stopped entries using their stored duration.
pub fn billable_seconds(entry: &TimeEntry) -> i64 {
    if entry.billable && !entry.is_running() {
        entry.duration
    } else {
        0
    }
}

pub fn weekly_billable_seconds(entries: &[TimeEntry]) -> BTreeMap<NaiveDate, i64> {
    let mut weeks = BTreeMap::new();
    for entry in entries {
        let seconds = billable_seconds(entry);
        if seconds == 0 {
            continue;
        }
        let date = entry.start.with_timezone(&Utc).date_naive();
        let monday = date - chrono::Duration::days(date.weekday().num_days_from_monday() as i64);
        *weeks.entry(monday).or_insert(0) += seconds;
    }
    weeks
}

pub fn format_weekly_bill(weeks: &BTreeMap<NaiveDate, i64>) -> String {
    if weeks.is_empty() {
        return "(no data)\n".to_string();
    }
    let mut output = String::new();
    let mut total = 0;
    for (week, seconds) in weeks {
        output.push_str(&format!("{}  {seconds}s\n", week.format("%Y-%m-%d")));
        total += seconds;
    }
    output.push_str(&format!("Total  {total}s\n"));
    output
}

impl BillWeeklyCommand {
    pub async fn execute(
        api_client: impl ApiClient,
        since: Option<String>,
        until: Option<String>,
    ) -> ResultWithDefaultError<()> {
        let (since, until) = utilities::normalize_time_entry_list_filters(since, until)?;
        let entries = api_client.get_time_entries_filtered(since, until).await?;
        let output = format_weekly_bill(&weekly_billable_seconds(&entries));
        io::stdout()
            .write_all(output.as_bytes())
            .expect("failed to print");
        Ok(())
    }
}

